#include <bits/stdc++.h>
using namespace std;

#define FOR_LOOP(i,st,ed) for(int i=st;i<=ed;++i)
#define REV_LOOP(i,st,ed) for(int i=st;i>=ed;--i)
typedef long long LL;

inline int input() {
    int x=0,f=1;char c;
    while((c=getchar()) && (c<'0'||c>'9') && c!='-');
    if(c=='-'){f=-1;c=getchar();}
    do {x=(x<<3)+(x<<1)+(c^'0');} while((c=getchar())>='0' && c<='9');
    return x*f;
}

inline LL inputLong() {
    LL x=0,f=1;char c;
    while((c=getchar()) && (c<'0'||c>'9') && c!='-');
    if(c=='-'){f=-1;c=getchar();}
    do {x=(x<<3)+(x<<1)+(c^'0');} while((c=getchar())>='0' && c<='9');
    return x*f;
}

const int MAXN=32,MOD=1e9+7;

inline void addTo(int &x,int y){
    x+=y;
    if(x>=MOD) x-=MOD;
}

struct MatrixType {
    int mat[MAXN][MAXN];
    void reset() {
        memset(mat,0,sizeof(mat));
    }
    void print() {
        for(int i=1;i<=n+1;++i){
            for(int j=1;j<=n+1;++j){
                printf("%d%c",mat[i][j],j==n+1?'\n':' ');
            }
        }
        putchar('\n');
    }
    MatrixType operator*(const MatrixType &rhs) const {
        MatrixType res; res.reset();
        for(int i=1;i<=n+1;++i)
            for(int j=1;j<=n+1;++j)
                for(int k=1;k<=n+1;++k)
                    addTo(res.mat[i][j],(long long)mat[i][k]*rhs.mat[k][j]%MOD);
        return res;
    }
};

int n;
MatrixType baseMat, A[MAXN], prefix[MAXN], suffix[MAXN], answer;

int main() {
#ifndef ONLINE_JUDGE
    freopen("matrix.in","r",stdin);
    freopen("matrix.out","w",stdout);
#endif
    LL m= inputLong(); n= input();
    baseMat.reset();
    for(int i=1;i<=n;++i) baseMat.mat[i][i]=1;
    answer=baseMat;
    for(int i=1;i<=n;++i){
        A[i]=baseMat;
        A[i].mat[i][i]=1;
    }
    prefix[0]=baseMat; suffix[n+1]=baseMat;
    for(;m; m/=n){
        LL u=m%n;
        if(u){
            LL s=0;
            for(LL v=m;v;v/=n) s=(s+v/n)%n;
            u=(s+u-1)%n+1;
            for(;u!=s;--u){
                if(u<=0) u+=n;
                answer=A[u]*answer;
            }
        }
        for(int i=1;i<=n;++i) prefix[i]=prefix[i-1]*A[i];
        for(int i=n;i>=1;--i) suffix[i]=A[i]*suffix[i+1];
        for(int i=1;i<=n;++i) A[i]=suffix[i]*prefix[i-1];
    }
    int total=1;
    for(int i=1;i<=n;++i) addTo(total,answer.mat[n+1][i]);
    printf("%d\n",total);
    return 0;
}
